def build():
 d=Diagram(KEY,'TuckER relation-conditioned core',SOURCE,'TuckER.forward','Only relation embedding, learned core contraction, hidden_dropout1 and subject BMM; subject input is post bn0/input_dropout plus original e1.size(1) metadata. Excludes bn1, output table scoring, sigmoid/loss/task training.',dict(d1=8,d2=6,relation_count='R',hidden_dropout1=.3,subject_boundary='x after bn0/input_dropout; before x.view',shape_boundary='e1.size(1) from original E(e1_idx), shape only',output_boundary='x after bmm and restore; before bn1',constructor_core_device='cuda',core_executed=False,mode='caller train/eval'))
 init=d.ref('TuckER.__init__');d.input('subject','Subject features after input Dropout','[B,8]');d.input('relation','Relation IDs r_idx','[B]');d.input('core','Owned learned 3-way core W','[6,8,8]',kind='parameter',source=init,**{k:v for k,v in REQUIRED['core'].items() if k!='shape'})
 d.input('e1shape','Original subject embedding WIDTH','e1.size(1) = 8',kind='control',expression='e1.size(1)',value_operand=False,origin='E(e1_idx) before bn0/input_dropout')
 d.node('relationlookup','Owned relation embedding R','embedding','[B,6]',0,source=[init,d.entry],**REQUIRED['relationlookup'],owned_weight_shape='[R,6]');d.node('subjectview','View subject as row per batch','tensor','[B,1,8]',0)
 d.stage('condition','Contract relation into core','[B,8,8]',1,[('mm','r @ core.view(6,-1)','matmul','[B,64]',REQUIRED['condition.mm']),('reshape','View conditioned matrix','tensor','[B,8,8]',dict()),('dropout','Hidden Dropout1 .3','dropout','[B,8,8]',REQUIRED['condition.dropout'])],source=[init,d.entry],suppress_input_boundary=True)
 d.node('multiply','Subject row @ conditioned matrix','bmm','[B,1,8]',2,**REQUIRED['multiply']);d.node('restore','Restore feature axis','tensor','[B,8]',3)
 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='right' if r=='shape_dependency' or t=='multiply' and s=='subjectview' else 'out',ds='right' if r=='shape_dependency' or t=='multiply' and s=='subjectview' else 'in',sp='shape' if r=='shape_dependency' else 'out')
 return d.build(d.entry,'[B,8]','TuckERCore.md',['Owned relation embedding R[r_idx] contracts with owned core W[d2,d1,d1] to form one relation-conditioned square matrix per batch item. Subject features then multiply that matrix in ordered bmm.','hidden_dropout1 applies to the conditioned matrix BEFORE subject multiplication; it is not dropout of the final entity score.','Core constructor explicitly creates a CUDA tensor using NumPy random initialization. That is recorded as a runtime boundary; neither initialization nor CUDA/model code is executed.','Selected boundary is a reusable feature-transformation suffix. It excludes input preprocessing and the later tied entity embedding scoring; no full knowledge-graph task model is claimed.'],['Do not draw relation as a gate multiplying subject elementwise, collapse the 3-way core into a plain Linear, or include unrelated classifier/sigmoid in this module.'])
